<script setup lang="ts">
import {computed,ref} from 'vue'
import {Search,Plus,Star,Cigarette,Wine,ArrowUpRight,Pencil,Database,Globe,Check,X,LoaderCircle,Info,Calculator} from 'lucide-vue-next'
import RecalculateDialog from './RecalculateDialog.vue'
import {api,state,saveRow,refresh} from '../api'
import type {Row} from '../types'
import {money,number} from '../types'
import {productPrice,productName} from '../productPricing'
const emit=defineEmits<{edit:[collection:string,row?:Row,preset?:Record<string,any>];changed:[];notify:[message:string]}>()
const search=ref(''),kind=ref('ALL'),favorites=ref(false),catalogOpen=ref(false),catalogQuery=ref(''),candidates=ref<any[]>([]),catalogMessage=ref(''),loading=ref(false),error=ref(''),selectedCandidate=ref<any>(null)
const catalogWarnings=ref<string[]>([]),recalcRow=ref<Row|null>(null)
const products=computed(()=>(state.collections.products||[]).filter(p=>(kind.value==='ALL'||p.kind===kind.value)&&(!favorites.value||p.favorite)&&`${p.brand} ${p.name} ${p.variant} ${p.aliases||''} ${p.barcode||''}`.toLowerCase().includes(search.value.toLowerCase())))

async function favorite(p:Row){try{await saveRow('products',{...p,favorite:!p.favorite},p);await refresh();emit('changed')}catch(e){error.value=(e as Error).message}}
async function catalogSearch(network=false){loading.value=true;error.value='';candidates.value=[];selectedCandidate.value=null;try{const r=await api<any>(`/catalog/search?q=${encodeURIComponent(catalogQuery.value.trim())}${network?'&refresh=true':''}`);candidates.value=Array.isArray(r)?r:r.candidates||r.results||[];catalogMessage.value=r.message||r.note||'';catalogWarnings.value=r.warnings||[]}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function importCandidate(){if(!selectedCandidate.value)return;loading.value=true;try{await api('/catalog/import',{method:'POST',body:JSON.stringify({candidate:selectedCandidate.value})});await refresh();emit('changed');emit('notify','商品资料已保存，可点“设置单价”确认这个种类的价格。');selectedCandidate.value=null;catalogOpen.value=false}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
</script>
<template><div class="products-page"><div class="page-intro"><div><h2>让常用的，下次更好记。</h2><p>每个种类保存自己的单价，记录时选择种类即可自动算费。</p></div><div class="toolbar"><button class="button secondary" @click="catalogOpen=true;error='';catalogSearch(false)"><Globe :size="17"/>查找商品资料</button><button class="button primary" @click="emit('edit','products',undefined,{kind:kind==='ALL'?'SMOKING':kind})"><Plus :size="17"/>添加商品</button></div></div><div class="product-filters"><div class="segmented"><button v-for="k in [{v:'ALL',l:'全部商品'},{v:'SMOKING',l:'香烟'},{v:'ALCOHOL',l:'酒类'}]" :key="k.v" :class="{active:kind===k.v}" @click="kind=k.v">{{k.l}}</button></div><label class="search-box"><Search :size="17"/><input v-model="search" placeholder="搜索品牌、规格或条码"/></label><button class="filter-toggle" :class="{active:favorites}" @click="favorites=!favorites"><Star :size="16"/>常用</button></div><p v-if="error&&!catalogOpen" class="error-box">{{error}}</p><div v-if="!products.length" class="panel empty-state"><Database :size="36"/><strong>{{search?'没有找到匹配商品':'先放进你常用的品牌'}}</strong><p>可以手动添加带单价的种类，也可以先导入商品资料，待核对后设置单价。</p><button class="button primary" @click="emit('edit','products')"><Plus :size="17"/>添加商品</button></div><div class="product-grid"><article v-for="p in products" :key="p.id" class="product-card" :class="p.kind==='SMOKING'?'smoking':'alcohol'"><div class="product-card-top"><span class="product-icon"><Cigarette v-if="p.kind==='SMOKING'" :size="30" :stroke-width="1.4"/><Wine v-else :size="30" :stroke-width="1.4"/></span><button class="icon-button favorite" :class="{isFavorite:p.favorite}" title="加入或移出常用" @click="favorite(p)"><Star :size="18" :fill="p.favorite?'currentColor':'none'"/></button></div><span class="product-brand">{{p.brand||'未填写品牌'}}</span><h3>{{productName(p)}}</h3><p class="product-variant">{{p.variant||'标准规格'}} · {{p.kind==='SMOKING'?`${p.unitCount??'—'} 根 / 包`:`${p.bottleMl??'—'} ml / 瓶`}}</p><div class="product-specs" v-if="p.kind==='SMOKING'"><div><span>焦油</span><strong>{{p.tarMg??'—'}}<small>mg</small></strong></div><div><span>烟气烟碱</span><strong>{{p.nicotineMg??'—'}}<small>mg</small></strong></div><div><span>一氧化碳</span><strong>{{p.coMg??'—'}}<small>mg</small></strong></div></div><div class="product-specs" v-else><div><span>酒精度</span><strong>{{p.abv??'—'}}<small>% vol</small></strong></div><div><span>整瓶纯酒精</span><strong>{{p.abv!=null&&p.bottleMl?number(p.bottleMl*p.abv/100*0.789,1):'—'}}<small>g</small></strong></div><div><span>折合 42 度白酒</span><strong>{{p.abv!=null&&p.bottleMl?number(Number(p.bottleMl)*Number(p.abv)/42,1):'—'}}<small>ml</small></strong></div></div><div class="product-price"><div><span>{{productPrice(p).type==='REFERENCE'?'参考单价':'种类单价'}} / {{p.kind==='SMOKING'?'包':'瓶'}}</span><strong>{{money(productPrice(p).amount)}}</strong><small class="price-state">{{productPrice(p).confirmed?'按本人消耗量自动计费':'请设置并确认种类单价'}}</small></div><button class="text-link" @click="emit('edit','products',p)">设置单价 <Pencil :size="14"/></button></div><footer><span class="tag" :class="{mint:p.verified}">{{p.verified?'已核对资料':'待核对资料'}}</span><div><a v-if="p.sourceUrl" :href="p.sourceUrl" class="icon-button" title="查看资料来源" target="_blank" rel="noopener noreferrer"><ArrowUpRight :size="17"/></a><button class="icon-button" title="预览历史重算" @click="recalcRow=p"><Calculator :size="16"/></button><button class="icon-button" title="编辑商品" @click="emit('edit','products',p)"><Pencil :size="16"/></button></div></footer></article></div><div class="soft-notice"><Info :size="16"/><span>香烟成分是包装标示值，不是人体吸收量。低焦油不代表更安全。商品参考价与实际成交价分别保存。</span></div>
<div v-if="catalogOpen" class="overlay" @click.self="catalogOpen=false"><section class="drawer"><header class="drawer-header"><div><small>CATALOG LOOKUP</small><h2>查找商品资料</h2></div><button class="icon-button" title="关闭" @click="catalogOpen=false"><X :size="20"/></button></header><div class="drawer-body"><p class="muted">检索仅发送商品关键词，不发送个人记录。导入前请核对品牌、规格和来源。</p><form class="catalog-search" @submit.prevent="catalogSearch(false)"><input v-model="catalogQuery" placeholder="品牌、型号、条码或具体商品页链接"/><button class="button primary" :disabled="loading"><LoaderCircle v-if="loading" :size="17" class="spin"/><Search v-else :size="17"/>本地检索</button></form><button class="button secondary full-width" :disabled="loading" @click="catalogSearch(true)"><Globe :size="16"/>按需联网更新商品资料</button><p v-if="error" class="error-box">{{error}}</p><p v-if="catalogMessage" class="hint">{{catalogMessage}}</p><p v-for="(warning,i) in catalogWarnings" :key="i" class="hint">{{warning}}</p><div v-for="(candidate,i) in candidates" :key="i" class="catalog-candidate" :class="{selected:selectedCandidate===candidate}" @click="selectedCandidate=candidate"><span class="tag">{{candidate.sourceLabel||candidate.source||'商品资料'}}</span><h3>{{(candidate.product||candidate).brand}} {{(candidate.product||candidate).name}}</h3><p>{{(candidate.product||candidate).variant}} · {{(candidate.product||candidate).kind==='SMOKING'?`${(candidate.product||candidate).unitCount??'—'} 根/包`:`${(candidate.product||candidate).bottleMl??'—'} ml · ${(candidate.product||candidate).abv??'—'}% vol`}}</p><p>{{candidate.note}}</p><p class="catalog-price">参考价：{{money(candidate.price?.amount)}} · {{candidate.price?.channel||'渠道待补'}}<br/>资料日期：{{candidate.product?.sourceDate||candidate.price?.effectiveDate||'待补充'}} · 导入后待核对</p><a v-if="candidate.sourceUrl||(candidate.product||candidate).sourceUrl" :href="candidate.sourceUrl||(candidate.product||candidate).sourceUrl" target="_blank" rel="noopener noreferrer" @click.stop>查看来源</a><Check v-if="selectedCandidate===candidate" :size="18"/></div><div v-if="!candidates.length&&!loading" class="empty-state compact"><Globe :size="30"/><strong>从完整的商品名称开始</strong><p>资料源没有覆盖时，可以手动添加或导入本地资料。</p></div><div v-if="selectedCandidate" class="meta-box">选中资料只作为待核对商品保存。参考价格不会修改过去的记录，也不会自动成为本次实际购买价。</div></div><footer class="drawer-footer"><button class="button secondary" @click="catalogOpen=false">关闭</button><button class="button primary" :disabled="!selectedCandidate||loading" @click="importCandidate"><Check :size="17"/>确认导入资料</button></footer></section></div><RecalculateDialog v-if="recalcRow" collection="products" :source-id="recalcRow.id" @close="recalcRow=null" @saved="recalcRow=null;emit('changed');emit('notify','历史记录已按确认的预览重算。')"/></div></template>
